// Original concise lessons following the NSU second-year syllabus, S. K. Vodopyanov.
export const YEAR_TWO_SOURCE='http://old.math.nsc.ru/~matanalyse/PROGR02.pdf';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(title,body,formula)=>({title,body:body.split('\n').map(p=>'<p>'+esc(p)+'</p>').join(''),formula});
const ex=(title,statement,steps,result)=>({title,statement,steps,result});
const c=(id,title,symbol,theory,workedExamples,deep,takeaway)=>({id,title,symbol,theory,workedExamples,deep,takeaway,subtitle:theory.slice(0,3).map(t=>t.title).join('. ')+'.',card:title,yearTwo:true,summaryFormula:theory[0].formula,sources:[['НГУ: программа 3–4-го семестров, С. К. Водопьянов',YEAR_TWO_SOURCE]],prerequisites:'Используются определения и теоремы предыдущих глав курса. При необходимости вернитесь к пределам, линейным отображениям и дифференциалу.'});
export const YEAR_TWO_CHAPTERS=[
c('higher','Высшие производные и локальные отображения','DF · D²F',[
t('Повторение: дифференциал и правило цепочки','Для F:U⊆ℝⁿ→ℝᵐ, U открыто, дифференциал DF(a) — линейное отображение, для которого F(a+h)=F(a)+DF(a)h+o(‖h‖). В координатах это матрица Якоби. Если F дифференцируема в a, а G — в F(a), то D(G∘F)(a)=DG(F(a))DF(a). Векторная теорема о среднем даёт оценку через норму производной на отрезке; равенство с одной общей промежуточной точкой для всех координат в общем случае неверно.','‖F(b)−F(a)‖≤sup₀≤t≤1‖DF(a+t(b−a))‖·‖b−a‖ для C¹-отображения'),
t('Однородные функции и теорема Эйлера','Пусть область U — конус: x∈U, t>0 влекут tx∈U. Функция f однородна степени k, если f(tx)=tᵏf(x). Если она дифференцируема, дифференцирование по t при t=1 даёт ∇f(x)·x=kf(x). Обратно, это дифференциальное равенство на конусе приводит к однородности вдоль лучей решением одномерного уравнения для f(tx).','Σᵢ xᵢ∂ᵢf(x)=k f(x)'),
t('Высшие дифференциалы и мультииндексы','Для Cʳ-функции Dᵏf(a) — симметричная k-линейная форма, k≤r. Мультииндекс α=(α₁,…,αₙ) состоит из неотрицательных целых чисел; |α|=Σαᵢ, α!=∏αᵢ!, hᵅ=∏hᵢᵅⁱ. Симметричность означает независимость смешанной производной от порядка дифференцирования при достаточной непрерывности. Она не следует из одного формального существования двух смешанных производных.','Dᵏf(a)[h,…,h]=Σ|α|=k (k!/α!) ∂ᵅf(a)hᵅ'),
t('Тейлор и алгебра приближений','Для f∈Cʳ около a формула Тейлора имеет остаток o(‖h‖ʳ): f(a+h)=Σ|α|≤r∂ᵅf(a)hᵅ/α!+o(‖h‖ʳ). Многочлен этого порядка единственен. Для произведения функций перемножают их многочлены и отбрасывают члены степени выше r; для суммы складывают. Для векторного отображения формулу применяют покоординатно.','Tʳₐ(fg)=члены степени ≤r в произведении Tʳₐf · Tʳₐg'),
t('Теорема об обратном отображении','Если F∈C¹(U,ℝⁿ) и det DF(a)≠0, существуют окрестности a и F(a), между которыми F задаёт C¹-диффеоморфизм. Производная локального обратного равна (DF(x))⁻¹ в соответствующих точках. Если F∈Cʳ, r≥1, обратное также Cʳ. Это локальный вывод: он не доказывает глобальную инъективность. При нулевом якобиане теорема ответа не даёт.','D(F⁻¹)(F(a))=(DF(a))⁻¹'),
t('Неявная функция и выпрямление','Пусть F:ℝⁿ×ℝᵐ→ℝᵐ класса Cʳ, F(a,b)=0, det DᵧF(a,b)≠0. Локально уравнение F(x,y)=0 эквивалентно y=φ(x), где φ∈Cʳ, и Dφ=−(DᵧF)⁻¹DₓF вдоль графика. Это следует из теоремы об обратном отображении для (x,y)↦(x,F(x,y)). Такая замена координат выпрямляет множество решений.','Dφ(x)=−[DᵧF(x,φ(x))]⁻¹DₓF(x,φ(x))'),
t('Постоянный ранг и функциональная зависимость','Если ранг DF равен r во всей некоторой окрестности a, подходящие локальные диффеоморфизмы аргументов и значений приводят F к виду (u₁,…,uᵣ,0,…,0). Постоянства ранга в одной точке недостаточно для этой формулировки. Если число компонент m>r, образ локально лежит на r-мерном подмногообразии и компоненты удовлетворяют m−r независимым локальным соотношениям.','rank DF≡r локально ⇒ локальная нормальная форма ранга r')],
[ex('Однородность','f(x,y)=x²+3y².',['f(tx,ty)=t²f(x,y), степень однородности 2.','∇f·(x,y)=2x²+6y²=2f.'],'Тождество Эйлера выполнено.'),ex('Обратимость линейного отображения','F(x,y)=(2x,3y).',['DF=diag(2,3), det DF=6≠0.','F⁻¹(u,v)=(u/2,v/3), его производная diag(1/2,1/3).'],'Локальная и в данном примере глобальная обратимость.'),ex('Нулевой якобиан не решает всё','f(x)=x³ в нуле.',['f′(0)=0, поэтому теорема об обратном отображении неприменима.','Функция всё же имеет непрерывную обратную кубического корня, но та не имеет конечной производной в 0.'],'Нужно различать обратимость и C¹-диффеоморфизм.')],
'Не может существовать общая промежуточная точка для произвольного векторного отображения. Для F(t)=(t²,t³) на [0,1] равенство F(1)−F(0)=F′(c) потребовало бы одновременно 2c=1 и 3c²=1; решения нет. Оценка через операторную норму остаётся верной.',
'Высшие производные описывают многолинейные приближения. Ненулевой якобиан даёт локальный диффеоморфизм; постоянный ранг и невырожденный блок производной позволяют описывать локальное строение множества решений.'),

c('smooth','Многообразия и условные экстремумы','TₐM · NₐM',[
t('Вложенное гладкое многообразие','k-мерное Cʳ-подмногообразие M⊆ℝⁿ локально параметризуется Cʳ-отображением φ из открытого множества ℝᵏ с рангом Dφ=k, взаимно однозначным и гомеоморфным на соответствующую часть M. Переходы между допустимыми координатами — Cʳ-диффеоморфизмы. Глобальной карты может не существовать: сферу нельзя покрыть одной обычной картой такого вида.','φ:V⊆ℝᵏ→M, rank Dφ=k'),
t('Регулярное множество уровня','Если g:U⊆ℝⁿ→ℝᵐ класса Cʳ, r≥1, и rank Dg=m в точке a с g(a)=0, то около a множество g=0 является многообразием размерности n−m. Независимость градиентов ограничений — та же гипотеза ранга. Невыполнение этой гипотезы не доказывает, что множество не многообразие: выбранная система уравнений может быть неудачной.','dim{g=0}=n−m локально в регулярной точке'),
t('Касательное пространство','Касательное пространство TₐM состоит из скоростей гладких кривых в M, проходящих через a. В локальной параметризации a=φ(u) оно равно образу Dφ(u). Для регулярного множества g=0 из правила цепочки получаем TₐM=ker Dg(a). Это линейное пространство векторов, приложенных в a; аффинная касательная плоскость — a+TₐM.','TₐM=im Dφ=ker Dg(a)'),
t('Нормальное пространство','В евклидовом ℝⁿ нормальное пространство NₐM — ортогональное дополнение TₐM. Для регулярных ограничений g₁=…=gₘ=0 независимые ∇g₁(a),…,∇gₘ(a) образуют базис NₐM. В частности, для сферы ‖x‖²=R² при a≠0 нормальное направление совпадает с a.','NₐM=span{∇g₁(a),…,∇gₘ(a)}'),
t('Множители Лагранжа','Пусть f и ограничения g класса C¹, точка a регулярна и является локальным экстремумом f на g=0. Тогда df(a) зануляется на TₐM, то есть ∇f(a)=Σλᵢ∇gᵢ(a). Вместе с g(a)=0 это система необходимых условий. Решения — кандидаты; нерегулярные точки исследуются отдельно, а глобальные экстремумы требуют анализа всего допустимого множества.','∇f=Σλᵢ∇gᵢ,  g=0'),
t('Достаточное условие на касательном пространстве','Для C²-данных рассмотрим лагранжиан ℒ=f−Σλᵢgᵢ в стационарной регулярной точке. Положительная определённость квадратичной формы D²ℒ(a) на ненулевых векторах TₐM даёт строгий условный минимум; отрицательная — максимум. Неопределённость на TₐM исключает экстремум. Полуопределённость сама по себе ответа не даёт.','D²ℒ(a)[v,v]>0 для v∈TₐM∖{0} ⇒ строгий условный минимум'),
t('Локальные и глобальные вопросы','Координаты и теоремы о ранге дают локальное описание. Для глобального экстремума непрерывной функции на непустом компактном многообразии можно гарантировать существование минимума и максимума и затем сравнить все кандидаты. При наличии края отдельно исследуют край; условия внутренней точки не заменяют эту проверку.','M компактно, f непрерывна ⇒ minₘ f и maxₘ f достигаются')],
[ex('Касательная к сфере','M={x²+y²+z²=1}, a=(0,0,1).',['Dg(a)v=2v_z, поэтому касательное пространство задаётся v_z=0.','Нормальное пространство — ось вектора (0,0,1); аффинная касательная плоскость z=1.'],'TₐM={(v_x,v_y,0)}.'),ex('Лагранж на окружности','Найти экстремумы x+y при x²+y²=1.',['Из (1,1)=λ(2x,2y) следует x=y.','Кандидаты (±1/√2,±1/√2) с одинаковыми знаками. Окружность компактна.'],'Максимум √2, минимум −√2.'),ex('Плохое уравнение гладкого множества','g(x,y)=x², множество g=0.',['Градиент равен нулю во всех точках множества, поэтому регулярная теорема для этой g не работает.','Само множество — прямая x=0, задаваемая регулярным уравнением x=0.'],'Вырожденное описание не означает негладкость множества.')],
'Необходимое условие Лагранжа следует из линейной алгебры. При экстремуме df(a)v=0 для любого касательного v. Значит ∇f(a) ортогонален ker Dg(a). Ортогональное дополнение этого ядра совпадает с линейной оболочкой независимых строк Dg(a), то есть градиентов ограничений.',
'Многообразие локально имеет координаты меньшей размерности. Касательные векторы удовлетворяют линеаризованным ограничениям; для экстремума важна вторая производная лагранжиана именно на касательном пространстве.'),

c('measure','Измеримые множества и мера Лебега','μ(⋃Aₙ)=Σμ(Aₙ)',[
t('σ-алгебра и мера','σ-алгебра 𝒜 подмножеств X содержит X, замкнута относительно дополнений и счётных объединений. Мера μ:𝒜→[0,+∞] удовлетворяет μ(∅)=0 и счётной аддитивности: мера объединения попарно непересекающихся Aₙ равна сумме их мер. Измеримое пространство — (X,𝒜), пространство с мерой — (X,𝒜,μ). Одной конечной аддитивности для общей теории недостаточно.','Aᵢ∩Aⱼ=∅ при i≠j ⇒ μ(⋃ₙAₙ)=Σₙμ(Aₙ)'),
t('Внешняя мера и критерий Каратеодори','Внешняя мера μ* задаётся на всех подмножествах X, равна нулю на пустом множестве, монотонна и счётно полуаддитивна. Множество A измеримо по Каратеодори, если для любого E⊆X выполнено μ*(E)=μ*(E∩A)+μ*(E∖A). Такие множества образуют σ-алгебру, а ограничение μ* на неё — полная мера.','∀E⊆X: μ*(E)=μ*(E∩A)+μ*(E∖A)'),
t('Мера Лебега','Внешняя мера Лебега в ℝⁿ получается инфимумом сумм объёмов счётных покрытий прямоугольными параллелепипедами. Измеримые по Каратеодори множества образуют полную σ-алгебру; мера совпадает с обычным объёмом прямоугольника. Борелевская σ-алгебра порождена открытыми множествами. Все борелевские множества измеримы по Лебегу; дополнение нулевых борелевских множеств всеми их подмножествами даёт завершение меры.','λₙ(∏[aᵢ,bᵢ])=∏(bᵢ−aᵢ)'),
t('Нулевые множества и почти всюду','Множество нулевой меры может быть бесконечным и даже несчётным. Каждое счётное множество в ℝⁿ имеет меру ноль; стандартное канторово множество также имеет меру ноль, хотя несчётно. Свойство выполнено почти всюду, если множество исключений имеет меру ноль. Полнота меры означает измеримость любого подмножества нулевого множества.','f=g почти всюду ⇔ μ({x:f(x)≠g(x)})=0'),
t('Непрерывность меры по множествам','При A₁⊆A₂⊆… имеем μ(⋃Aₙ)=lim μ(Aₙ), включая бесконечность. Для убывающих A₁⊇A₂⊇… равенство μ(∩Aₙ)=lim μ(Aₙ) гарантировано, если хотя бы один член имеет конечную меру. Условие существенно: для Aₙ=[n,+∞) все меры бесконечны, а пересечение пусто.','Aₙ↑A ⇒ μ(Aₙ)↑μ(A)'),
t('Измеримая функция','Вещественная или расширенно вещественная f измерима, если {x:f(x)>a}∈𝒜 для каждого a∈ℝ. Эквивалентно, прообразы борелевских множеств измеримы. Суммы, произведения и поточечные пределы измеримых вещественных функций измеримы там, где операции определены. Непрерывная функция борелевски измерима. Для полной меры изменение на нулевом множестве сохраняет измеримость.','f измерима ⇔ f⁻¹((a,+∞])∈𝒜 для всех a∈ℝ'),
t('Простые функции и приближение','Простая измеримая функция принимает конечное число значений и записывается как Σcᵢ1_Aᵢ по измеримому разбиению. Любая неотрицательная измеримая f является поточечным пределом неубывающей последовательности неотрицательных простых функций: используют двоичные ступени и отсечение больших значений. В отличие от непрерывного приближения, здесь допускаются измеримые ступени.','sₙ(x)=2⁻ⁿ⌊2ⁿ min(f(x),n)⌋; sₙ↑f')],
[ex('Мера рациональных чисел','Найти λ(ℚ∩[0,1]).',['Перечислим рациональные qₖ в отрезке. Каждая одноточечная часть имеет меру 0.','Счётная полуаддитивность даёт меру объединения не больше суммы нулей.'],'Мера 0.'),ex('Конечная аддитивность','A=[0,1], B=[1,3]. Найти меру A∪B.',['Пересечение состоит из точки 1 и имеет меру 0.','λ(A∪B)=λ(A)+λ(B)−λ(A∩B)=1+2.'],'Мера 3.'),ex('Непрерывность сверху','Aₙ=(0,1/n).',['Меры 1/n стремятся к 0, первая мера конечна.','Пересечение пусто: ноль не входит, любую положительную точку исключает достаточно большой n.'],'λ(∩Aₙ)=0.')],
'Почему счётное множество имеет меру ноль. Для перечисленных точек xₖ и любого ε>0 выберем вокруг xₖ прямоугольники объёма меньше ε·2⁻ᵏ. Суммарный объём покрытия меньше ε. Инфимум объёмов всех покрытий равен нулю.',
'Мера определена на σ-алгебре и счётно аддитивна. «Почти всюду» относится к нулевой мере исключений, а не к конечности или малой мощности множества. Измеримость обеспечивает возможность строить интеграл.')
];
YEAR_TWO_CHAPTERS.push(
c('lebesgue','Интеграл Лебега и предельный переход','∫ lim fₙ',[
t('Неотрицательный интеграл','Для простой функции s=Σcᵢ1_Aᵢ, cᵢ≥0, интеграл равен Σcᵢμ(Aᵢ), где множества разбиения измеримы. Для измеримой f≥0 интеграл определяется как супремум интегралов простых s≤f. Он может быть бесконечным.','∫f dμ=sup{∫s dμ:0≤s≤f, s простая}'),
t('Знак и пространство L¹','Пишут f=f⁺−f⁻, |f|=f⁺+f⁻. Конечный интеграл существует, если ∫|f|<∞; тогда ∫f=∫f⁺−∫f⁻. Выражение ∞−∞ не определяют. В L¹ отождествляют функции, равные почти всюду; норма равна ∫|f|. Интеграл линеен, |∫f|≤∫|f|.','L¹={f измерима:∫|f|<∞}/равенство почти всюду'),
t('Теорема Леви','Если 0≤fₙ↑f почти всюду и все функции измеримы, то ∫fₙ↑∫f. Конечности интегралов не требуется. Это теорема о монотонной сходимости; для произвольной немонотонной последовательности её вывод неверен.','0≤fₙ↑f ⇒ lim∫fₙ=∫f'),
t('Лемма Фату','Для измеримых fₙ≥0 интеграл нижнего предела не превосходит нижнего предела интегралов. Знак существенен. Доказательство применяет Леви к gₙ=infₖ≥ₙfₖ. Равенство без дополнительных условий не гарантировано.','∫liminf fₙ≤liminf∫fₙ'),
t('Теорема Лебега о мажорируемой сходимости','Пусть fₙ→f почти всюду и |fₙ|≤g почти всюду для всех n, где g∈L¹. Тогда f∈L¹, ∫|fₙ−f|→0 и ∫fₙ→∫f. Нужна одна интегрируемая мажоранта для всей последовательности, а не отдельная для каждого n.','fₙ→f п.в., |fₙ|≤g∈L¹ ⇒ fₙ→f в L¹'),
t('Ряды и полнота L¹','Если Σ∫|uₙ|<∞, то Σ|uₙ(x)| конечна почти всюду, сумма принадлежит L¹ и интеграл суммы равен сумме интегралов. Из этого выводят полноту L¹: всякая фундаментальная по норме последовательность имеет предел по норме. Это утверждение называют теоремой Рисса — Фишера.','Σ‖uₙ‖₁<∞ ⇒ Σuₙ сходится в L¹ и абсолютно п.в.'),
t('Разные виды сходимости','Сходимость в L¹ влечёт сходимость по мере по оценке μ{|fₙ−f|>ε}≤‖fₙ−f‖₁/ε. На пространстве конечной меры сходимость почти всюду влечёт сходимость по мере. Обратный переход к почти всюду гарантирован для некоторой подпоследовательности. Почти всюду не влечёт L¹: n1_(0,1/n)→0 на (0,1), а интегралы равны 1.','‖fₙ−f‖₁→0 ⇒ fₙ→f по мере'),
t('Связь с интегралом Римана','Ограниченная функция на отрезке интегрируема по Риману тогда и только тогда, когда множество её точек разрыва имеет меру ноль. В этом случае интегралы Римана и Лебега совпадают. Условно сходящийся несобственный интеграл не является конечным интегралом Лебега по всей области, поскольку модуль не интегрируем.','R-интегрируемость ограниченной f ⇔ λ(точки разрыва f)=0')],
[ex('Равенство почти всюду','f=1_ℚ на [0,1].',['Рациональные числа имеют меру ноль, поэтому f=0 почти всюду.','Интеграл Лебега равен 0, но разрыв есть в каждой точке, поэтому интеграла Римана нет.'],'∫f=0.'),ex('Концентрация массы','fₙ=n1_(0,1/n) на (0,1).',['Каждая положительная точка со временем вне носителя.','Высота n умножается на длину 1/n; интеграл равен 1. Общей L¹-мажоранты нет, иначе теорема Лебега дала бы предел интегралов 0.'],'Почти всюду 0, но не в L¹.'),ex('Применение мажоранты','fₙ(x)=xⁿ на [0,1].',['Предел равен 0 почти всюду; исключение x=1 имеет меру ноль.','0≤xⁿ≤1 и единица интегрируема на [0,1].'],'∫xⁿdx=1/(n+1)→0.')],
'В доказательстве мажорируемой сходимости применяют Фату к 2g−|fₙ−f|≥0. Получают 2∫g≤2∫g−limsup∫|fₙ−f|; конечность ∫g позволяет вычесть его. Отсюда норма разности стремится к нулю.',
'Для перестановки предела и интеграла проверяют конкретную теорему: монотонность, неотрицательность или общую интегрируемую мажоранту.'),

c('multiple','Произведения мер и замена переменных','∫∫f · |det DΦ|',[
t('Произведение мер','Для σ-конечных пространств с мерами произведение определяется на произведении σ-алгебр и удовлетворяет (μ×ν)(A×B)=μ(A)ν(B). σ-конечность означает покрытие счётным числом множеств конечной меры. В ℝⁿ×ℝᵐ это согласуется с мерой Лебега после завершения.','λₙ₊ₘ(A×B)=λₙ(A)λₘ(B)'),
t('Теорема Тонелли','Для неотрицательной измеримой f на произведении σ-конечных пространств оба повторных интеграла совпадают с интегралом по произведению. Допускается значение +∞; интегрируемость модуля заранее не нужна. Измеримость сечений и соответствующих интегралов понимается с обычными оговорками о завершении меры.','f≥0 ⇒ ∫f d(μ×ν)=∫(∫f dν)dμ=∫(∫f dμ)dν'),
t('Теорема Фубини','Если ∫|f|d(μ×ν)<∞, сечения интегрируемы почти всюду, повторные интегралы существуют и равны общему интегралу. Для знакопеременной f нельзя переставлять интегрирование только на основании существования обоих повторных интегралов.','f∈L¹(μ×ν) ⇒ ∫∫f=∫∫f в обоих порядках'),
t('Якобиан замены','Пусть Φ:U→V — C¹-диффеоморфизм открытых областей ℝⁿ. Для неотрицательной измеримой f, а также для интегрируемой f, интеграл по V равен интегралу f∘Φ с весом |det DΦ| по U. Модуль определителя нужен для неориентированного объёма. Если отображение не инъективно, простая формула требует поправки на кратность.','∫ᵥf(y)dy=∫ᵤf(Φ(x))|det DΦ(x)|dx'),
t('Полярные и сферические координаты','В плоскости x=r cosθ, y=r sinθ, якобиан равен r при r>0. В ℝ³ для радиуса r, полярного угла θ∈(0,π), азимута φ∈(0,2π) множитель равен r²sinθ. Лучи, ось и границы карт исключают для диффеоморфизма; их объёмная мера нулевая.','dxdy=r drdθ; dxdydz=r²sinθ drdθdφ'),
t('Объёмы и особенность степени','Объём единичного шара ℝⁿ равен ωₙ=πⁿᐟ²/Γ(n/2+1). Радиальное интегрирование имеет вес nωₙrⁿ⁻¹. Поэтому ‖x‖⁻ᵖ интегрируема около нуля ровно при p<n, а вне единичного шара — при p>n. При p=n возникает логарифмическая расходимость.','∫ℝⁿh(‖x‖)dx=nωₙ∫₀∞h(r)rⁿ⁻¹dr для h≥0'),
t('Принцип Кавальери и нулевые множества','Мера тела равна интегралу мер его сечений по Тонелли. C¹-отображение между открытыми частями ℝⁿ локально липшицево и переводит нулевые множества в нулевые: область покрывается счётным числом компактных окрестностей с ограниченной производной. Это свойство относится к n-мерной мере при одинаковой размерности.','λₙ(E)=∫ℝλₙ₋₁(E_t)dt')],
[ex('Площадь треугольника','D={0<x<1, 0<y<1−x}.',['Сечение при x имеет длину 1−x.','∫₀¹(1−x)dx=1/2.'],'Площадь 1/2.'),ex('Момент диска','Вычислить ∫_{x²+y²<1}x²dxdy.',['В полярных координатах интеграл равен ∫₀¹r³dr·∫₀²πcos²θdθ.','Множители равны 1/4 и π.'],'Интеграл π/4.'),ex('Когда Фубини неприменима','f=(x²−y²)/(x²+y²)² на (0,1)².',['При интегрировании сначала по y получаем 1/(1+x²), затем π/4.','При интегрировании сначала по x получаем −1/(1+y²), затем −π/4. Модуль f не интегрируем у начала координат.'],'Повторные интегралы различны; условия Фубини нарушены.')],
'Для линейного отображения A объёмы параллелепипедов меняются в |det A| раз. Дифференцируемая замена на малых областях приближается своим дифференциалом; предельный переход приводит к весу |det DΦ|. Контроль покрытия и нулевых множеств необходим для строгого доказательства.',
'Тонелли работает с неотрицательностью, Фубини — с интегрируемостью модуля. Замена переменных требует якобиана и проверки области однозначности.'),

c('parameters','Интегралы с параметром. Гамма- и бета-функции','Γ(s) · B(p,q)',[
t('Непрерывность по параметру','Пусть f(x,a) измерима по x, непрерывна по a почти для всех x около a₀ и |f(x,a)|≤g(x)∈L¹ с одной g для всех этих a. Тогда I(a)=∫f(x,a)dx непрерывна в a₀. Это следствие теоремы Лебега для любой последовательности параметров a→a₀.','I(a)→I(a₀) при общей локальной L¹-мажоранте'),
t('Дифференцирование под интегралом','Достаточные условия: f(x,a) дифференцируема по a почти для всех x на интервале, ∂ₐf измерима по x и |∂ₐf(x,a)|≤g(x)∈L¹ локально равномерно по a; f(·,a₀)∈L¹. Тогда I′(a)=∫∂ₐf. Разностные отношения оцениваются по теореме о среднем.','d/da ∫f(x,a)dx=∫∂ₐf(x,a)dx'),
t('Переменные пределы','Для непрерывных f и ∂ₐf на соответствующей компактной области и C¹-функций α,β правило Лейбница содержит вклады обоих концов. Для бесконечных концов нужны дополнительные условия сходимости; их нельзя считать обычными конечными границами.','I′(a)=f(β(a),a)β′(a)−f(α(a),a)α′(a)+∫α(a)^β(a)∂ₐf(x,a)dx'),
t('Гамма-функция','Для s>0 положим Γ(s)=∫₀∞tˢ⁻¹e⁻ᵗdt. Около нуля сходимость требует s>0, на бесконечности экспонента сильнее степени. Интегрирование по частям даёт Γ(s+1)=sΓ(s), Γ(1)=1, следовательно Γ(n+1)=n!. На каждом компактном подынтервале s>0 допустимы производные под интегралом с множителями lnᵏt.','Γ(s+1)=sΓ(s), s>0'),
t('Бета-функция','При p,q>0 B(p,q)=∫₀¹tᵖ⁻¹(1−t)ᑫ⁻¹dt. Замена u=rs, v=r(1−s) в произведении двух гамма-интегралов имеет якобиан r и даёт B(p,q)=Γ(p)Γ(q)/Γ(p+q). Положительность позволяет применить Тонелли.','B(p,q)=Γ(p)Γ(q)/Γ(p+q)'),
t('Гауссов интеграл','Квадрат ∫ℝe⁻ˣ²dx равен интегралу e⁻⁽ˣ²⁺ʸ²⁾ по плоскости. Полярные координаты дают 2π∫₀∞e⁻ʳ²rdr=π. Положительный корень равен √π; подстановка t=x² затем даёт Γ(1/2)=√π.','∫ℝe⁻ᵃˣ²dx=√(π/a), a>0'),
t('Формулы Эйлера и асимптотика','Для s>0 верен предел Эйлера — Гаусса Γ(s)=limₙ n!nˢ/[s(s+1)…(s+n)]. Формула отражения Γ(s)Γ(1−s)=π/sin(πs) здесь рассматривается при 0<s<1. Формула Стирлинга описывает относительную, а не абсолютную ошибку факториала. Эти результаты требуют отдельных доказательств; из одной рекурсии Γ они не следуют.','n!/[√(2πn)(n/e)ⁿ]→1')],
[ex('Целый аргумент','Вычислить Γ(5).',['Γ(1)=1.','Четырежды используем Γ(s+1)=sΓ(s): 4·3·2·1.'],'Γ(5)=24.'),ex('Бета-интеграл','Вычислить B(2,3).',['Γ(2)=1, Γ(3)=2, Γ(5)=24.','B(2,3)=1·2/24.'],'B(2,3)=1/12.'),ex('Производная по параметру','I(a)=∫₀∞e⁻ᵃˣdx, a>0. Найти I′(2).',['I(a)=1/a. Около a=2 производная под интегралом мажорируется x e⁻ˣ.','I′(a)=−∫₀∞xe⁻ᵃˣdx=−1/a².'],'I′(2)=−1/4.')],
'Соотношение бета- и гамма-функций выводится из двойного интеграла uᵖ⁻¹vᑫ⁻¹e⁻⁽ᵘ⁺ᵛ⁾. После замены r=u+v, s=u/(u+v) переменные разделяются: Γ(p+q)B(p,q). Якобиан равен r, а не 1.',
'Параметр можно вносить под знак предела или производной только после проверки соответствующих условий. Гамма- и бета-функции систематизируют важные семейства интегралов.'),

c('uniformintegrals','Равномерная сходимость несобственных интегралов','supₐ |хвост|→0',[
t('Определение равномерного хвоста','Пусть I_R(a)=∫ᵦᴿf(x,a)dx и каждый конечный интеграл определён. Интегралы сходятся равномерно на A, если I_R→I равномерно по a∈A при R→∞. Здесь изучается равномерная сходимость несобственных интегралов; термин не следует смешивать с понятием равномерной интегрируемости семейств в теории меры.','supₐ∈A|I(a)−I_R(a)|→0'),
t('Критерий Коши','Равномерная сходимость равносильна условию: для каждого ε>0 найдётся R₀, такое что для любых R₂>R₁>R₀ и всех a∈A модуль ∫R₁^R₂f меньше ε. Один R₀ должен подходить для всего множества параметров.','supₐ∈A|∫R₁^R₂ f(x,a)dx|<ε при R₂>R₁>R₀'),
t('Мажоранта','Если |f(x,a)|≤g(x) для всех a и ∫ᵦ∞g<∞, то несобственные интегралы сходятся равномерно и абсолютно. Остаток оценивается интегралом g по хвосту. Условие достаточно, но не необходимо.','supₐ|∫ᴿ∞f|≤∫ᴿ∞g→0'),
t('Равномерный признак Дирихле','Достаточная версия: первообразные F(R,a)=∫ᵦᴿf(x,a)dx ограничены одной константой по R,a; g(x,a) монотонна по x, C¹ по x и стремится к нулю равномерно по a. Тогда ∫fg сходится равномерно. Интегрирование по частям оценивает хвост через g и его вариацию.','supᴿ,ₐ|F(R,a)|≤C, supₐ|g(R,a)|→0'),
t('Равномерный признак Абеля','Если ∫f сходится равномерно по a, а g монотонна по x и ограничена одной константой по x,a, то ∫fg сходится равномерно (например, при C¹-зависимости g от x). Доказательство использует малость хвостовых первообразных f и ограниченную вариацию g.','равномерная сходимость ∫f + равномерно ограниченный монотонный g ⇒ ∫fg'),
t('Непрерывность и производная','Если I_R непрерывны по параметру и сходимость равномерна локально, предел I непрерывен. Для производной достаточно C¹-функций I_R, равномерной сходимости I_R′ на компактном интервале и сходимости I_R в одной точке; тогда I′=lim I_R′. Отдельно обосновывают дифференцирование конечного интеграла.','I_R′⇒J и I_R(a₀) сходится ⇒ I′=J'),
t('Интегрирование по параметру','На конечном интервале параметров равномерная сходимость I_R позволяет переставить предел и интеграл по a. Для каждого конечного R перестановка двух интегралов должна быть разрешена отдельно, например непрерывностью на прямоугольнике. На бесконечном интервале параметров одной равномерности недостаточно.','limᴿ→∞∫α^β I_R(a)da=∫α^β I(a)da')],
[ex('Компакт параметров','f=e⁻ᵃˣ, x≥0, a∈[1,2].',['Хвост ∫ᴿ∞e⁻ᵃˣdx=e⁻ᵃᴿ/a.','Максимум по a достигается при a=1 и равен e⁻ᴿ.'],'Равномерная сходимость.'),ex('Потеря равномерности','Тот же интеграл при a∈(0,2].',['Для каждого a>0 интеграл конечен и равен 1/a.','При фиксированном R хвост e⁻ᵃᴿ/a неограничен, когда a→0.'],'Поточечная сходимость есть, равномерной нет.'),ex('Интеграл по параметру','Найти ∫₁²(∫₀∞e⁻ᵃˣdx)da.',['На [1,2] сходимость равномерна и конечные интегралы непрерывны.','Внутренний интеграл равен 1/a.'],'Результат ln 2.')],
'Равномерный критерий Коши — обычный критерий полноты для ограниченных функций от параметра в супремум-норме, применённый к разностям I_R−I_S. Даже когда сами I_R не ограничены, можно фиксировать один I_S и рассматривать равномерно ограниченные разности.',
'Равномерность означает одну оценку хвоста для всех параметров. Сходимость каждого отдельного интеграла этого не гарантирует.'),

c('approximation','Свёртка, сглаживание и приближение','f*ρₑ → f',[
t('Бесконечные произведения','Для положительных множителей 1+uₙ бесконечное произведение имеет конечный ненулевой предел тогда и только тогда, когда сходится Σln(1+uₙ). Условие Σ|uₙ|<∞ достаточно, если все uₙ>−1. Для uₙ≥0 сходимость произведения к конечному ненулевому пределу равносильна сходимости Σuₙ.','∏ₙ(1+uₙ)=exp(Σₙln(1+uₙ))'),
t('Формула Валлиса','Последовательные интегралы степеней синуса на [0,π/2] связаны интегрированием по частям. Сравнение соседних степеней даёт произведение Валлиса. Отдельный конечный множитель не равен пределу произведения.','∏ₙ₌₁∞ 4n²/(4n²−1)=π/2'),
t('Свёртка','Для f,g∈L¹(ℝⁿ) определяют (f*g)(x)=∫f(x−y)g(y)dy почти всюду. Тонелли даёт ‖f*g‖₁≤‖f‖₁‖g‖₁. Свёртка коммутативна и ассоциативна в L¹; интегралы функций перемножаются.','∫(f*g)=(∫f)(∫g)'),
t('Приближающая единица','Пусть ρ≥0, ρ∈L¹, ∫ρ=1, ρₑ(x)=ε⁻ⁿρ(x/ε), ε>0. Масса вне любой фиксированной окрестности нуля стремится к нулю. Тогда f*ρₑ→f в Lᵖ для 1≤p<∞. Для ограниченной равномерно непрерывной f сходимость равномерна.','‖f*ρₑ−f‖ₚ→0, f∈Lᵖ, 1≤p<∞'),
t('Непрерывность сдвига и сглаживание','Для f∈Lᵖ, p<∞, ‖f(·−h)−f‖ₚ→0. Она позволяет оценить ошибку свёртки средним норм сдвигов. Если ρ∈C_c^∞, то свёртка с локально интегрируемой f гладкая, производные переносятся на ядро; при компактных носителях носитель суммы содержится в сумме носителей.','Dᵅ(f*ρₑ)=f*(Dᵅρₑ)'),
t('Плотность гладких функций','C_c^∞(ℝⁿ) плотно в Lᵖ(ℝⁿ), 1≤p<∞: сначала отсекают дальний хвост и большие значения, затем сглаживают. Аналогичное утверждение для нормы L∞ произвольных измеримых функций неверно: скачок нельзя равномерно приблизить непрерывными функциями.','∀f∈Lᵖ ∀δ>0 ∃φ∈C_c^∞:‖f−φ‖ₚ<δ'),
t('Теорема Вейерштрасса','Для непрерывной f на [0,1] многочлены Бернштейна Bₙf=Σₖ₌₀ⁿf(k/n)C(n,k)xᵏ(1−x)ⁿ⁻ᵏ сходятся к f равномерно. На произвольном отрезке используют линейную замену аргумента. Это приближение многочленами, а не утверждение о сходимости ряда Тейлора.','‖Bₙf−f‖∞→0'),
t('Тригонометрическое приближение','Для непрерывной 2π-периодической f средние Фейера её сумм Фурье являются тригонометрическими многочленами и сходятся к f равномерно. Следовательно, тригонометрические многочлены плотны в пространстве непрерывных периодических функций по супремум-норме.','σₙf=(S₀f+…+Sₙ₋₁f)/n ⇒ f')],
[ex('Свёртка индикаторов','f=g=1_[0,1].',['(f*g)(x) — длина пересечения [0,1] и [x−1,x].','Получается x на [0,1], 2−x на [1,2] и 0 вне [0,2].'],'Треугольная функция с интегралом 1.'),ex('Скачок','Можно ли равномерно приблизить 1_(0,∞) непрерывными функциями на ℝ?',['Равномерный предел непрерывных функций непрерывен.','У индикатора есть разрыв в 0. Сглаживание всё же даёт локальную Lᵖ-сходимость при p<∞.'],'Равномерного приближения нет.'),ex('Начало произведения Валлиса','Перемножить первые два множителя.',['При n=1 множитель 4/3.','При n=2 множитель 16/15; произведение 64/45.'],'64/45, предел всех произведений π/2.')],
'Для ограниченной равномерно непрерывной f разбивают интеграл ошибки свёртки на |y|<δ и |y|≥δ. В первой части разность f(x−y)−f(x) мала одновременно по x, во второй она ограничена 2‖f‖∞, а масса ядра стремится к нулю.',
'Способ приближения и норму нужно называть явно. Гладкое приближение в Lᵖ не означает равномерного приближения в точках скачка.'),

c('surface','Мера Хаусдорфа и поверхностный интеграл','Jₖφ=√det(DφᵀDφ)',[
t('Мера Хаусдорфа','Для целого k≥1 нормированная внешняя мера Хаусдорфа строится покрытием множествами малого диаметра: Hᵏ(E)=(ωₖ/2ᵏ)limδ↓0 infΣ(diam Uᵢ)ᵏ, где E⊆⋃Uᵢ и diam Uᵢ≤δ. Нормировка обеспечивает Hᵏ=λₖ в ℝᵏ. В частности, H¹ измеряет длину, H² — площадь.','ωₖ=объём единичного шара ℝᵏ'),
t('Измеримость и геометрические оценки','Хаусдорфова внешняя мера является метрической, поэтому борелевские множества измеримы по Каратеодори. Липшицево отображение с константой L удовлетворяет Hᵏ(F(E))≤LᵏHᵏ(E). Изодиаметрическое неравенство λₙ(E)≤ωₙ(diam E/2)ⁿ связывает нормировку Хаусдорфа с обычным объёмом.','Hᵏ(F(E))≤LᵏHᵏ(E)'),
t('Якобиан площади','Для C¹-параметризации φ:U⊆ℝᵏ→ℝⁿ ранга k матрица DφᵀDφ — матрица Грама касательных векторов. Её определитель даёт квадрат k-мерного изменения площади. При инъективной параметризации ∫φ(U)f dHᵏ=∫ᵤf(φ(u))Jₖφ(u)du.','Jₖφ=√det(DφᵀDφ)'),
t('Кратность и атлас','При неинъективном C¹-отображении формула площади учитывает число прообразов N(φ,U,y): ∫ᵤg(φ(u))Jₖφ du=∫g(y)N(φ,U,y)dHᵏ(y) для g≥0. При интегрировании по многообразию карты перекрываются; используют разбиение единицы, а не сумму площадей всех карт с повторным счётом.','N(φ,U,y)=число точек u∈U с φ(u)=y'),
t('График, кривая, поверхность вращения','Для графика z=g(x), g:ℝᵏ→ℝ, площадь имеет вес √(1+‖∇g‖²). Для регулярной кривой γ вес длины равен ‖γ′‖. Для вращения графика положительного радиуса r(x) вокруг оси x площадь равна 2π∫r(x)√(1+r′(x)²)dx при отсутствии повторного покрытия.','dS=√(1+‖∇g‖²)dx; ds=‖γ′(t)‖dt'),
t('Индуцированная мера','Неориентированный поверхностный интеграл использует положительную меру Hᵏ на гладком многообразии. Выбор направления параметризации не меняет значение. Это отличается от интеграла дифференциальной формы, знак которого зависит от ориентации.','∫ₘf dS не зависит от ориентации M'),
t('Формула кообъёма','Пусть F:U⊆ℝⁿ→ℝᵐ, m≤n, класса C¹ и ранга m во всей U. Тогда для g≥0 интеграл gJₘF по U равен интегралу по y от интегралов g по слоям F⁻¹(y), с мерой Hⁿ⁻ᵐ. Для знакопеременной g требуется интегрируемость модуля с соответствующим весом. Это регулярная версия формулы кообъёма.','∫ᵤg√det(DF DFᵀ)dx=∫ℝᵐ[∫F⁻¹(y)g dHⁿ⁻ᵐ]dy')],
[ex('График плоскости','φ(x,y)=(x,y,x+y). Найти якобиан площади.',['Столбцы Dφ равны (1,0,1) и (0,1,1).','Матрица Грама [[2,1],[1,2]] имеет определитель 3.'],'J₂φ=√3.'),ex('Сфера','Площадь сферы радиуса 2.',['Параметризация сферическими углами имеет вес R²sinθ.','∫₀²π∫₀π4sinθ dθdφ=16π.'],'Площадь 16π.'),ex('Слои проекции','F(x,y)=x на (0,1)×(0,2), g=1.',['DF=(1,0), J₁F=1.','Каждый непустой слой имеет длину 2; интегрируем по x∈(0,1).'],'Обе стороны формулы кообъёма равны 2.')],
'Векторы столбцов Dφ задают малый касательный параллелепипед. Квадрат его k-мерного объёма равен определителю матрицы их попарных скалярных произведений. Отсюда возникает матрица Грама и квадратный корень в формуле площади.',
'Площадь параметризованного многообразия вычисляется через матрицу Грама. Нужно различать меру образа, площадь с кратностью и ориентированный интеграл.'),

c('forms','Дифференциальные формы и формула Стокса','∫∂Mω=∫M dω',[
t('Кососимметричные формы','k-форма в точке — кососимметричная k-линейная функция касательных векторов. Гладкое поле таких форм записывают Σ_I a_I(x)dxᵢ₁∧…∧dxᵢₖ по возрастающим индексам. Внешнее произведение билинейно; перестановка соседних 1-форм меняет знак, поэтому dx∧dx=0.','α∧β=(−1)ᵖᑫβ∧α для степеней p,q'),
t('Внешняя производная','Для ω=Σa_I dx_I положим dω=Σⱼ,I ∂ⱼa_I dxⱼ∧dx_I. Для C²-коэффициентов d(dω)=0: смешанные производные симметричны, а внешнее произведение кососимметрично. Выполняется правило d(α∧β)=dα∧β+(−1)ᵖα∧dβ.','d²=0'),
t('Обратный образ формы','Для гладкого Φ обратный образ Φ*ω вычисляется подстановкой DΦ в каждый аргумент формы. В координатах заменяют переменные и их дифференциалы. Операция согласуется с внешним произведением и внешней производной при достаточной гладкости.','d(Φ*ω)=Φ*(dω)'),
t('Ориентация и край','Ориентация задаётся согласованным выбором знака упорядоченного касательного базиса; переходы ориентированных карт имеют положительный определитель. Не всякое многообразие ориентируемо. Ориентация края задаётся правилом «внешняя нормаль первая»: (ν,v₁,…,vₖ₋₁) должен быть положительным базисом многообразия.','ориентация ∂M: сначала внешняя нормаль'),
t('Цепи и интегрирование','На ориентированной карте интеграл k-формы сводится к интегралу её коэффициента после обратного образа; разбиение единицы согласует карты. Для ориентированных кубических цепей граница — знаковая сумма граней. Каждое ребро границы границы входит дважды с противоположными знаками.','∂²=0'),
t('Общая формула Стокса','Пусть M — компактное ориентированное гладкое k-многообразие с краем, ω — C¹-форма степени k−1 в его окрестности. Тогда ∫∂Mω=∫M dω. Допускается некомпактное M при компактном носителе формы. Классические формулы Грина, Стокса и Гаусса получаются выбором степени и координатной записи; они разобраны в следующей главе.','∫∂Mω=∫M dω'),
t('Замкнутость и точность','Форма замкнута, если dω=0, и точна, если ω=dη. Точная форма замкнута. По лемме Пуанкаре гладкая замкнутая форма положительной степени на звёздной открытой области точна. На произвольной области это неверно: угловая форма (−y dx+x dy)/(x²+y²) на проколотой плоскости имеет интеграл 2π по окружности.','точная ⇒ замкнутая; обратное зависит от области'),
t('Независимость пути','Для C¹-1-формы на связной открытой области точность эквивалентна независимости интеграла от пути, или нулю интеграла по всем замкнутым кусочно гладким путям. Условие dω=0 обеспечивает локальный потенциал; для глобального нужно условие на область, например звёздность.','ω=df ⇒ ∫γ ω=f(γ(b))−f(γ(a))'),
t('Форма Гаусса и топологическое следствие','В ℝⁿ∖{0}, n≥2, форма ω=(1/|Sⁿ⁻¹|)Σᵢ(−1)ⁱ⁻¹xᵢ‖x‖⁻ⁿdx₁∧…∧d̂xᵢ∧…∧dxₙ замкнута и имеет интеграл 1 по единичной сфере с внешней ориентацией. Стокс исключает гладкую ретракцию замкнутого шара на сферу. Теорема Брауэра утверждает, что любое непрерывное отображение замкнутого шара в себя имеет неподвижную точку; переход к непрерывным отображениям требует дополнительного приближения.','F:B̄ⁿ→B̄ⁿ непрерывно ⇒ ∃x:F(x)=x')],
[ex('Знак внешнего произведения','Вычислить dy∧dx.',['Переставляем две 1-формы.','Знак (−1)¹ равен −1.'],'dy∧dx=−dx∧dy.'),ex('Производная 1-формы','ω=x dy на ℝ².',['d(x dy)=dx∧dy+x d(dy).','Второе слагаемое равно нулю.'],'dω=dx∧dy.'),ex('Стокс на диске','ω=(−y dx+x dy)/2 на единичном диске.',['dω=dx∧dy, интеграл по диску равен π.','Положительно ориентированная окружность идёт против часовой стрелки.'],'∮∂Dω=π.')],
'Если бы существовала гладкая ретракция r шара на его сферу, обратный образ формы Гаусса был бы замкнут в шаре. Стокс дал бы нулевой интеграл по краю. Но на краю r тождественна, поэтому интеграл равен 1. Противоречие.',
'Внешняя производная и оператор границы согласованы формулой Стокса. Замкнутость формы — локальное условие; существование глобального потенциала зависит также от области.'),

c('fourier','Ряды и преобразование Фурье','f̂(ξ)=∫f(x)e⁻ⁱˣξdx',[
t('Комплексная запись','Комплексное число имеет вид a+ib, i²=−1; модуль √(a²+b²), сопряжение a−ib. Формула Эйлера eⁱᵗ=cos t+i sin t позволяет записать синус и косинус экспонентами. Интегралы комплексных функций берут по вещественной и мнимой частям.','eⁱᵗ=cos t+i sin t'),
t('Коэффициенты и ядро Дирихле','Для f∈L¹(−π,π), периодически продолженной, cₖ=(1/2π)∫₋π^πf(t)e⁻ⁱᵏᵗdt. Частичная сумма S_N=Σ|k|≤N cₖeⁱᵏˣ равна свёртке с ядром Дирихле и весом 1/(2π). Ядро меняет знак, его L¹-норма не ограничена по N.','D_N(t)=sin((N+1/2)t)/sin(t/2)'),
t('Риман — Лебег, локализация и Дини','Для L¹-функции cₖ→0; это не доказывает поточечной сходимости ряда. Принцип локализации: сходимость в точке определяется поведением в любой её окрестности. Достаточное условие Дини в точке непрерывности: ∫₀δ|f(x+t)+f(x−t)−2f(x)|/t dt<∞. Для кусочно C¹-периодической функции суммы сходятся к полусумме односторонних пределов.','S_Nf(x)→[f(x+0)+f(x−0)]/2 для кусочно C¹ f'),
t('Фейер и приближение','Средние σ_N=(S₀+…+S_N₋₁)/N имеют неотрицательное ядро K_N=(1/N)(sin(Nt/2)/sin(t/2))² с интегралом 2π. Они сходятся равномерно для непрерывных периодических f и в Lᵖ для 1≤p<∞. Усреднение сумм существенно для этого общего результата.','K_N≥0, (1/2π)∫₋π^πK_N=1'),
t('Парсеваль и геометрия','В L²(−π,π) тригонометрическая система полна: (1/2π)∫|f|²=Σ|cₖ|². Для гладких периодических функций применение к производной приводит к неравенству Виртингера и изопериметрическому неравенству для простой замкнутой плоской C¹-кривой: P²≥4πA, равенство для окружности. Ещё один классический результат — произведение sin(πz)/(πz)=∏ₙ≥1(1−z²/n²), сходящееся локально равномерно по комплексному z.','P²≥4πA'),
t('Преобразование Фурье','На ℝⁿ используем соглашение f̂(ξ)=∫f(x)e⁻ⁱˣ·ξdx без множителя перед прямым преобразованием. Для f∈L¹ преобразование ограниченно, непрерывно, стремится к нулю при ‖ξ‖→∞ и однозначно определяет класс f почти всюду. Для f,g∈L¹ преобразование свёртки равно произведению преобразований.','(f*g)̂=f̂ĝ; ‖f̂‖∞≤‖f‖₁'),
t('Пространство Шварца','Гладкая f принадлежит 𝒮(ℝⁿ), если все xᵅDᵝf ограничены для любых мультииндексов α,β. Гауссиана — пример. Преобразование Фурье сохраняет 𝒮; интегрирование по частям даёт (∂ⱼf)̂=iξⱼf̂. Условия убывания устраняют граничные слагаемые.','supₓ|xᵅDᵝf(x)|<∞ для всех α,β'),
t('Обращение и Планшерель','Если f∈L¹ и f̂∈L¹, обратный интеграл с множителем (2π)⁻ⁿ задаёт непрерывного представителя f; равенство исходной функции имеет место почти всюду и в её точках непрерывности. По Планшерелю преобразование продолжается на L² с нормировкой ‖f‖₂²=(2π)⁻ⁿ‖f̂‖₂². Для общей L²-функции прямой интеграл не обязан существовать абсолютно.','f(x)=(2π)⁻ⁿ∫f̂(ξ)eⁱˣ·ξdξ'),
t('Гауссиана и уравнение теплопроводности','При a>0 преобразование e⁻ᵃˣ² равно √(π/a)e⁻ξ²/(4a). Для ∂ₜu=Δu и начального f∈L¹ решение при t>0 задаётся u=G_t*f, где G_t(x)=(4πt)⁻ⁿᐟ²exp(−‖x‖²/(4t)). Его масса 1, преобразование e⁻ᵗ‖ξ‖², а u→f в L¹ при t↓0.','û(t,ξ)=e⁻ᵗ‖ξ‖²f̂(ξ)')],
[ex('Одна гармоника','f(x)=cos x. Найти c₁ и c₋₁.',['cos x=(eⁱˣ+e⁻ⁱˣ)/2.','Ортогональность экспонент зануляет остальные коэффициенты.'],'c₁=c₋₁=1/2.'),ex('Нормировка преобразования','f=e⁻ˣ². Найти f̂(0).',['При ξ=0 экспоненциальный множитель прямого преобразования равен 1.','Интеграл Гаусса по ℝ равен √π.'],'f̂(0)=√π.'),ex('Тепловая масса','Начальная функция f≥0 имеет интеграл 3.',['∫G_t=1.','По Тонелли ∫(G_t*f)=(∫G_t)(∫f).'],'При каждом t>0 масса решения равна 3.')],
'Преобразование производной для функции Шварца выводится интегрированием по частям: ∫f′(x)e⁻ⁱˣξdx=iξ∫f(x)e⁻ⁱˣξdx. Две производные дают −ξ². Поэтому уравнение теплопроводности переходит в обыкновенное уравнение ∂ₜû=−ξ²û, решение которого равно e⁻ᵗξ²f̂.',
'Сходимость рядов зависит от класса функции и способа суммирования. На ℝⁿ преобразование Фурье превращает свёртку в произведение, а дифференцирование — в умножение на частоту.')
);
